void assert_stdout_equals(stdout_capture_t *cap, const char *expected) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strcmp(actual, expected) != 0) {
        fprintf(stderr, "Stdout assertion failed:
");
        fprintf(stderr, "  Expected: "%s"
", expected);
        fprintf(stderr, "  Actual:   "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

